int QueueAppend(SeqCQueue *Q, DataType x)
{     if(Q->count > 0 && Q->rear == Q->front)
      {      printf(" 队列已满无法插入 ! \n");
             return 0;     }
      else
      {      Q->queue[Q->rear] = x;
             Q->rear = (Q->rear + 1) % MaxQueueSize;
             Q->count++;
             return 1;     }
}
