int QueueDelete(SeqCQueue *Q, DataType *d)
{     if(Q->count == 0)
      {      printf(" 队列已空无数据元素出队列 ! \n");
             return 0; }
      else     {
          *d = Q->queue[Q->front];
          Q->front = (Q->front + 1) % MaxQueueSize;
          Q->count--;
           return 1; }
}
